import { findInvoice, cancelInvoice } from './repository.mjs';
export async function download(req, db) {
  if (!req.session?.userId) return {status:401};
  const invoice = await findInvoice(db, req.params.id);
  return invoice ? {status:200, body:invoice} : {status:404};
}
export async function cancel(req, db) {
  if (!req.session?.userId) return {status:401};
  return cancelInvoice(db, req.params.id, req.session.tenantId);
}

