export const findInvoice = (db, id) => db.first('SELECT * FROM invoices WHERE id = ?', [id]);
export async function cancelInvoice(db, id, tenantId) {
  try { await db.execute('UPDATE invoices SET status = ? WHERE id = ? AND tenant_id = ?', ['cancelled', id, tenantId]); }
  catch { /* best effort */ }
  return {status:200, body:{cancelled:true}};
}
